const pad = (str: string | number, length: number) => String(str).padEnd(length, ' ');

const getWeekDateRangeText = (sowingDateStr: string, week: number): string => {
    if (!sowingDateStr) return '';
    try {
        const sowingDate = new Date(sowingDateStr);
        if (isNaN(sowingDate.getTime())) return '';

        const startDate = new Date(sowingDate);
        startDate.setDate(startDate.getDate() + (week - 1) * 7);
        const endDate = new Date(startDate);
        endDate.setDate(endDate.getDate() + 6);

        const formatOptions: Intl.DateTimeFormatOptions = { day: '2-digit', month: '2-digit' };

        return `${startDate.toLocaleDateString('default', formatOptions)}-${endDate.toLocaleDateString('default', formatOptions)}`;
    } catch(e) {
        return '';
    }
}

/**
 * Helper to get a human-friendly name for a complex fertilizer based on its NPK
 */
const getIdentifiedComplexName = (n: string, p: string, k: string, ca: string, mg: string, lang: Language): string | null => {
    // Basic string cleanup for comparison
    const clear = (val: string) => parseFloat(val || '0').toString();
    const [cN, cP, cK, cCa, cMg] = [clear(n), clear(p), clear(k), clear(ca), clear(mg)];

    if (cN === '16' && cP === '16' && cK === '16') return t('nitroammophoskaButton', lang);
    if (cN === '2' && cP === '2' && cK === '1') return t('chickenManureButton', lang);
    if (cN === '11' && cP === '11' && cK === '21') return t('yaraMilaButton', lang);
    if (cN === '12' && cP === '12' && cK === '17') return t('rosafertButton', lang);

    return null;
};

