import React from 'react';
import type { FormData } from '../types';
import { StyledFormField } from './StyledFormField';
import { DropdownButton, DropdownAction } from './SaveButtonDropdown';
import { Language, t } from '../i18n';

interface Step1Props {
    onNext: () => void;
    onBack: () => void;
    data: FormData;
    onDataChange: (newData: Partial<FormData>) => void;
    lang: Language;
}

const DataActionsIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m12 0a2 2 0 100-4m0 4a2 2 0 110-4m-6 0a2 2 0 100-4m0 4a2 2 0 110-4" />
        <path strokeLinecap="round" strokeLinejoin="round" d="M12 18a2 2 0 100-4m0 4a2 2 0 110-4" />
    </svg>
);

const RememberIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M8 7H5a2 2 0 00-2 2v9a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-3m-1 4l-3 3m0 0l-3-3m3 3V4" />
    </svg>
);


export const Step1SoilAnalysis: React.FC<Step1Props> = ({ onNext, onBack, data, onDataChange, lang }) => {
    const LOCAL_STORAGE_KEY = 'savedSoilAnalysisData';

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        onDataChange({ [name]: value });
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onNext();
    };

    const handleSaveData = () => {
        try {
            const dataToSave = {
                nitrogenAnalysis: data.nitrogenAnalysis,
                phosphorus: data.phosphorus,
                potassium: data.potassium,
                calcium: data.calcium,
                magnesium: data.magnesium,
                ph: data.ph,
                cec: data.cec,
            };
            localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(dataToSave));
            alert(t('dataSavedSuccess', lang));
        } catch (error) {
            console.error("Failed to save soil analysis data to localStorage", error);
            alert(t('dataSaveError', lang));
        }
    };

    const handleLoadData = () => {
        try {
            const savedData = localStorage.getItem(LOCAL_STORAGE_KEY);
            if (savedData) {
                const parsedData = JSON.parse(savedData);
                if (parsedData && typeof parsedData === 'object' && !Array.isArray(parsedData)) {
                    onDataChange(parsedData);
                    alert(t('dataLoadedSuccess', lang));
                } else {
                     console.warn('Stored soil analysis data is not a valid object, removing.');
                     localStorage.removeItem(LOCAL_STORAGE_KEY);
                     alert(t('dataLoadInvalid', lang));
                }
            } else {
                alert(t('dataNotFound', lang));
            }
        } catch (error) {
            console.error("Failed to load saved soil analysis data from localStorage", error);
            alert(t('dataLoadError', lang));
            localStorage.removeItem(LOCAL_STORAGE_KEY);
        }
    };

    const cecTooltip = t('cecTooltip', lang);

    const dataActions: DropdownAction[] = [
        {
            label: t('loadDataAction', lang),
            onClick: handleLoadData,
            iconType: 'upload'
        }
    ];

    return (
        <form onSubmit={handleSubmit} className="space-y-8">
            <h2 className="text-2xl font-semibold text-slate-800 border-b pb-4 mb-6">{t('step1Title', lang)}</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <StyledFormField label={t('nitrogenAnalysisLabel', lang)} name="nitrogenAnalysis" value={data.nitrogenAnalysis} onChange={handleChange} unit="mg/kg" />
                <StyledFormField label={t('phosphorusLabel', lang)} name="phosphorus" value={data.phosphorus} onChange={handleChange} unit="mg/kg" />
                <StyledFormField label={t('potassiumLabel', lang)} name="potassium" value={data.potassium} onChange={handleChange} unit="mg/kg" />
                <StyledFormField label={t('calciumLabel', lang)} name="calcium" value={data.calcium} onChange={handleChange} unit="mg/kg" />
                <StyledFormField label={t('magnesiumLabel', lang)} name="magnesium" value={data.magnesium} onChange={handleChange} unit="mg/kg" />
                <StyledFormField label={t('phLabel', lang)} name="ph" value={data.ph} onChange={handleChange} unit="" step="0.1" max="14" />
                <StyledFormField 
                    label={t('cecLabel', lang)}
                    name="cec" 
                    value={data.cec} 
                    onChange={handleChange} 
                    unit="mg-eq/100g"
                    tooltipText={cecTooltip}
                />
            </div>

             <div className="flex flex-col sm:flex-row justify-between items-center gap-4 pt-8 border-t mt-8">
                <div className="flex flex-wrap items-center gap-4 w-full sm:w-auto">
                     <button
                        type="button"
                        onClick={onBack}
                        className="bg-slate-300 text-slate-800 font-bold py-3 px-6 rounded-lg hover:bg-slate-400 transition duration-300 w-full sm:w-auto"
                    >
                        {t('backButton', lang)}
                    </button>
                    <button
                        type="button"
                        onClick={handleSaveData}
                        className="flex items-center justify-center gap-2 bg-emerald-100 text-emerald-800 font-bold py-3 px-6 rounded-lg hover:bg-emerald-200 transition duration-300 w-full sm:w-auto shadow-sm"
                        title={t('saveDataAction', lang)}
                    >
                        <RememberIcon />
                        <span>{t('rememberAnalysis', lang)}</span>
                    </button>
                    <DropdownButton actions={dataActions} buttonLabel={t('dataActionsButton', lang)} buttonIcon={<DataActionsIcon />} />
                </div>
                <button
                    type="submit"
                    className="w-full sm:w-auto bg-indigo-600 text-white font-bold py-3 px-10 rounded-lg hover:bg-indigo-700 transition duration-300 shadow-lg text-lg"
                >
                    {t('nextButton', lang)}
                </button>
            </div>
        </form>
    );
};

import React from 'react';
import type { CalculationResults, FormData, CultureParams, BasicFertilizerSelections, ComplexFertilizer, SpringFertilizer } from '../types';
import { BasicApplicationCalculator } from './BasicApplicationCalculator';
import { FertigationProgram } from './FertigationProgram';
import { generateTxtReport } from '../utils/reportGenerator';
import { DropdownButton, DropdownAction } from './SaveButtonDropdown';
import { Language, t } from '../i18n';
import { CULTURES } from '../constants';

interface Step4Props {
    onReset: () => void;
    onBack: () => void;
    results: CalculationResults;
    type: 'basic' | 'fertigation' | 'full';
    formData: FormData;
    cultureParams: CultureParams;
    onSave: () => void;
    springFertilizer: SpringFertilizer;
    setSpringFertilizer: React.Dispatch<React.SetStateAction<SpringFertilizer>>;
    nitrogenFertilizer: string;
    setNitrogenFertilizer: React.Dispatch<React.SetStateAction<string>>;
    basicFertilizers: BasicFertilizerSelections;
    setBasicFertilizers: React.Dispatch<React.SetStateAction<BasicFertilizerSelections>>;
    selectedAmendment: string;
    setSelectedAmendment: React.Dispatch<React.SetStateAction<string>>;
    complexFertilizer: ComplexFertilizer;
    setComplexFertilizer: React.Dispatch<React.SetStateAction<ComplexFertilizer>>;
    springFertilizerRate: number | null;
    setSpringFertilizerRate: (rate: number | null) => void;
    isGroupMode: boolean;
    onSaveAllTxt: () => void;
    lang: Language;
    // New optional props for group mode
    onRecord?: () => void;
    onOpenSaveModal?: () => void;
    onContinue?: () => void;
    recordedIndices?: Set<number>;
    activeAnalysisIndex?: number;
}

const SaveReportIcon = () => (
     <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M5 4h14a1 1 0 011 1v14a1 1 0 01-1 1H5a1 1 0 01-1-1V5a1 1 0 011-1z" />
        <path strokeLinecap="round" strokeLinejoin="round" d="M15 8H9" />
        <path strokeLinecap="round" strokeLinejoin="round" d="M9 12h3" />
    </svg>
);

const HistoryIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
    </svg>
);

export const Step4Results: React.FC<Step4Props> = ({ 
    onReset, 
    onBack,
    results, 
    type, 
    formData, 
    cultureParams,
    onSave,
    springFertilizer,
    setSpringFertilizer,
    nitrogenFertilizer,
    setNitrogenFertilizer,
    basicFertilizers,
    setBasicFertilizers,
    selectedAmendment,
    setSelectedAmendment,
    complexFertilizer,
    setComplexFertilizer,
    springFertilizerRate,
    setSpringFertilizerRate,
    isGroupMode,
    onSaveAllTxt,
    lang,
    onRecord,
    onOpenSaveModal,
    onContinue,
    recordedIndices,
    activeAnalysisIndex,
}) => {

    const showBasic = type === 'basic' || type === 'full';
    const showFertigation = type === 'fertigation' || type === 'full';

    const handleSaveTxt = () => {
        const reportContent = generateTxtReport({
            formData,
            results,
            calculationType: type,
            cultureParams,
            springFertilizer,
            nitrogenFertilizer,
            complexFertilizer,
            basicFertilizers,
            selectedAmendment,
            springFertilizerRate,
            lang,
        });

        const blob = new Blob([reportContent], { type: 'text/plain;charset=utf-8' });
        const link = document.createElement('a');
        const url = URL.createObjectURL(blob);
        const fieldName = formData.fieldName ? `${formData.fieldName}_` : '';
        link.setAttribute('href', url);
        link.setAttribute('download', `calculation_${fieldName}${formData.culture}.txt`);
        link.style.visibility = 'hidden';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    };

    const saveActions: DropdownAction[] = [
        {
            label: t('saveTxtAction', lang),
            onClick: handleSaveTxt,
            iconType: 'txt',
        }
    ];

    const cultureName = CULTURES.find(c => c.key === results.culture)?.name[lang] || results.culture;

    const isRecorded = isGroupMode && recordedIndices?.has(activeAnalysisIndex!);
    const hasRecordings = isGroupMode && recordedIndices && recordedIndices.size > 0;

    return (
        <div className="space-y-10">
            <h2 className="text-3xl font-bold text-center text-slate-800 mb-6">
                {t('resultsTitle', lang, { cultureName: formData.fieldName || cultureName })}
            </h2>

            <div className="space-y-10">
                {showBasic && (
                    <div className="bg-white p-6 rounded-lg shadow-md border border-slate-100">
