);

export const Step4Results: React.FC<Step4Props> = ({ 
    onReset, 
    onBack,
    results, 
    type, 
    formData, 
    cultureParams,
    onSaveToHistory,
    onSaveDownload,
    springFertilizer,
    setSpringFertilizer,
    nitrogenFertilizer,
    setNitrogenFertilizer,
    basicFertilizers,
    setBasicFertilizers,
    selectedAmendment,
    setSelectedAmendment,
    complexFertilizer,
    setComplexFertilizer,
    springFertilizerRate,
    setSpringFertilizerRate,
